h.del_flag='0'
  and h.activity_id=#{activityId}
  and h.hotel_name like concat('%',#{hotelName},'%')
  and h.sale_status=#{saleStatus}

order by h.sort_order asc, h.hotel_id asc

mapper.update:
update yc_hotel
hotel_name=#{hotelName}, phone=#{phone}, address=#{address}, cover_url=#{coverUrl}, sale_status=#{saleStatus}, sort_order=#{sortOrder}, update_by=#{updateBy}, remark=#{remark}, update_time=sysdate()
where hotel_id=#{hotelId}
